async function medical_evidence_search(params, userSettings, resources) {
  // Shared Core Engine for Gemini Chat Hub: Medical Grounded Search Plugin (v1.0.0)
  // Compiled into self-contained node:vm plugin functions by build_medical_plugin.mjs

  const startTimeMs = Date.now();
  const HARD_BUDGET_MS = 78000;
  function elapsedMs() {
    return Date.now() - startTimeMs;
  }
  function remainingBudgetMs() {
    return Math.max(0, HARD_BUDGET_MS - elapsedMs());
  }

  const isBrowserRuntime = typeof window !== "undefined" && typeof window.document !== "undefined";
  const envVars = typeof process !== "undefined" && process && process.env ? process.env : {};
  if (typeof globalThis !== "undefined" && typeof globalThis.structuredClone !== "function") {
    globalThis.structuredClone = (val) => JSON.parse(JSON.stringify(val));
  }

  function clamp(num, min, max) {
    return Math.max(min, Math.min(max, num));
  }
  function unique(arr) {
    return Array.from(new Set((arr || []).filter(Boolean)));
  }
  function toArray(v) {
    return Array.isArray(v) ? v.filter(Boolean) : [];
  }
  function truncate(text, max) {
    return !text || text.length <= max ? text || "" : text.slice(0, max);
  }
  function arrayBufferToBase64(arrayBuffer) {
    if (typeof Buffer !== "undefined") {
      return Buffer.from(arrayBuffer).toString("base64");
    }
    const bytes = new Uint8Array(arrayBuffer);
    let binary = "";
    const chunkSize = 32768;
    for (let i = 0; i < bytes.length; i += chunkSize) {
      binary += String.fromCharCode.apply(null, bytes.subarray(i, i + chunkSize));
    }
    return btoa(binary);
  }

  const uSettings = userSettings || {};
  const fallbackWorkerProxy = "https://unified-proxy.creativeappmaking.workers.dev";
  const rawProxy = (uSettings.proxyUrl !== void 0 ? String(uSettings.proxyUrl) : uSettings.workerUrl || fallbackWorkerProxy).trim().replace(/\/$/, "");
  const proxyBase = rawProxy || "";
  const vaultRef = (typeof vault !== "undefined" && vault) || (resources && resources.vault) || null;
  const storageRef = (typeof storage !== "undefined" && storage) || (typeof localStorage !== "undefined" && localStorage && typeof localStorage.get === "function" ? localStorage : null) || (resources && resources.storage) || null;

  function resolveSecret(...keys) {
    for (const k of keys) {
      if (uSettings[k] && String(uSettings[k]).trim() && !String(uSettings[k]).includes("{{")) {
        return String(uSettings[k]).trim();
      }
    }
    if (vaultRef && typeof vaultRef.getSecret === "function") {
      for (const k of keys) {
        const val = vaultRef.getSecret(k) || vaultRef.getSecret(k.toUpperCase());
        if (val && String(val).trim()) return String(val).trim();
      }
    }
    for (const k of keys) {
      const envVal = envVars[k] || envVars[k.toUpperCase()];
      if (envVal && String(envVal).trim()) return String(envVal).trim();
    }
    return "";
  }

  const geminiApiKey = resolveSecret("google_api_key", "gemini_api_key", "GOOGLE_API_KEY", "GEMINI_API_KEY", "GEMINI_FREE_API_KEY");
  const ncbiApiKey = resolveSecret("ncbi_api_key", "NCBI_API_KEY");
  const openfdaApiKey = resolveSecret("openfda_api_key", "OPENFDA_API_KEY");

  const rawModelId = String(uSettings.generative_model || "gemini-3.5-flash-lite").trim();
  const generativeModel = rawModelId.replace(/^(~?google\/|models\/)/i, "") || "gemini-3.5-flash-lite";
  const verificationEngine = uSettings.verification_engine || "hybrid_auto";
  const enableHop2Setting = uSettings.enable_hop2_verification || "auto";
  const actionOnError = uSettings.action_on_error || "return_diagnostic_json";

  const geminiDirectUrl = "https://generativelanguage.googleapis.com/v1beta/interactions";
  const geminiProxyUrl = proxyBase ? `${proxyBase}/proxy/${geminiDirectUrl}` : null;
  const decisionsDirectUrl = "https://generativelanguage.googleapis.com/v1beta/decisions";
  const decisionsProxyUrl = proxyBase ? `${proxyBase}/proxy/${decisionsDirectUrl}` : null;

  const today = (new Date()).toISOString().split("T")[0];
  const currentYear = today.split("-")[0];
  let transportState = "healthy";
  const diagnostics = {
    plugin_version: "1.0.0",
    generative_model: generativeModel,
    decisions_api_calls: 0,
    decisions_api_status: "not_invoked",
    generative_calls: 0,
    incomplete_generations: 0,
    api_calls: {}
  };

  function trackApiCall(apiName, ok) {
    if (!diagnostics.api_calls[apiName]) {
      diagnostics.api_calls[apiName] = { ok: 0, fail: 0 };
    }
    if (ok) diagnostics.api_calls[apiName].ok += 1;
    else diagnostics.api_calls[apiName].fail += 1;
  }

  function buildEndpointList(directUrl, proxiedUrl) {
    if (!isBrowserRuntime) {
      return [directUrl, proxiedUrl].filter(Boolean);
    }
    return [proxiedUrl, directUrl].filter(Boolean);
  }

  async function fetchWithTimeout(url, options, timeoutMs) {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeoutMs);
    try {
      return await fetch(url, { ...options, signal: controller.signal });
    } finally {
      clearTimeout(timer);
    }
  }

  let lastNcbiCallTimeMs = 0;
  async function paceNcbiRequest(url) {
    if (!/ncbi\.nlm\.nih\.gov/i.test(String(url || ""))) return;
    const minGap = ncbiApiKey ? 150 : 420;
    const now = Date.now();
    const scheduled = Math.max(now, lastNcbiCallTimeMs + minGap);
    lastNcbiCallTimeMs = scheduled;
    const waitMs = scheduled - now;
    if (waitMs > 0) {
      await new Promise((r) => setTimeout(r, waitMs));
    }
  }

  async function fetchPublicJson(url, apiName = "public_api", timeoutMs = 10000, { allowNotFound = false } = {}) {
    const endpoints = buildEndpointList(url, proxyBase ? `${proxyBase}/proxy/${url}` : null);
    let lastError = "fetch_failed";
    for (const target of endpoints) {
      for (let attempt = 0; attempt < 3; attempt++) {
        try {
          await paceNcbiRequest(target);
          const res = await fetchWithTimeout(target, {
            headers: {
              "User-Agent": "GeminiMedicalSearch/1.0 (https://ai.google.dev)",
              "Accept": "application/json,*/*"
            }
          }, timeoutMs);
          if (res.status === 429 && attempt < 2 && remainingBudgetMs() > 8000) {
            await new Promise((r) => setTimeout(r, 950 + attempt * 450));
            continue;
          }
          if (allowNotFound && res.status === 404) {
            return { ok: false, status: 404, data: null, error: "not_found" };
          }
          if (!res.ok) {
            lastError = `HTTP_${res.status}`;
            if (res.status === 404 || res.status === 400 || res.status === 403) break;
            break;
          }
          const text = await res.text();
          let parsed = null;
          try {
            parsed = JSON.parse(text);
          } catch (je) {
            if (allowNotFound) return { ok: false, status: res.status, data: null, error: "non_json_not_available" };
            throw je;
          }
          trackApiCall(apiName, true);
          return { ok: true, status: res.status, data: parsed, error: null };
        } catch (e) {
          lastError = e.message || "fetch_exception";
          break;
        }
      }
    }
    trackApiCall(apiName, false);
    return { ok: false, status: 0, data: null, error: lastError };
  }

  async function fetchPublicText(url, apiName = "public_api", timeoutMs = 12000, { allowNotFound = false } = {}) {
    const endpoints = buildEndpointList(url, proxyBase ? `${proxyBase}/proxy/${url}` : null);
    let lastError = "fetch_failed";
    for (const target of endpoints) {
      for (let attempt = 0; attempt < 2; attempt++) {
        try {
          await paceNcbiRequest(target);
          const res = await fetchWithTimeout(target, {
            headers: {
              "User-Agent": "Mozilla/5.0 (compatible; GeminiMedicalSearch/1.0; +https://ai.google.dev)",
              "Accept": "application/xml,text/xml,text/html,text/plain,*/*"
            }
          }, timeoutMs);
          if (res.status === 429 && attempt === 0 && remainingBudgetMs() > 8000) {
            await new Promise((r) => setTimeout(r, 650));
            continue;
          }
          if (allowNotFound && res.status === 404) {
            return { ok: false, status: 404, text: "", lastModified: null, error: "not_found" };
          }
          if (!res.ok) {
            lastError = `HTTP_${res.status}`;
            if (res.status === 404 || res.status === 403 || res.status === 400) break;
            break;
          }
          const text = await res.text();
          trackApiCall(apiName, true);
          return { ok: true, status: res.status, text, lastModified: res.headers.get("last-modified"), error: null };
        } catch (e) {
          lastError = e.message || "fetch_exception";
          break;
        }
      }
    }
    trackApiCall(apiName, false);
    return { ok: false, status: 0, text: "", lastModified: null, error: lastError };
  }

  async function storageCacheGet(key, maxAgeMs) {
    if (!storageRef || typeof storageRef.get !== "function") return null;
    try {
      const entry = await storageRef.get(key);
      if (entry && entry.timestamp && Date.now() - entry.timestamp < maxAgeMs) {
        return entry.data;
      }
    } catch (e) {}
    return null;
  }

  async function storageCacheSet(key, data) {
    if (!storageRef || typeof storageRef.set !== "function") return;
    try {
      await storageRef.set(key, { data, timestamp: Date.now() });
    } catch (e) {}
  }

  function decodeHtmlEntities(str) {
    if (!str) return "";
    return String(str)
      .replace(/&nbsp;/gi, " ")
      .replace(/&amp;/gi, "&")
      .replace(/&lt;/gi, "<")
      .replace(/&gt;/gi, ">")
      .replace(/&quot;/gi, '"')
      .replace(/&#39;|&apos;/gi, "'")
      .replace(/&ndash;/gi, "-")
      .replace(/&mdash;/gi, "--")
      .replace(/&#x([0-9a-fA-F]+);/g, (_, hex) => {
        const code = parseInt(hex, 16);
        return code > 0 && code <= 1114111 ? String.fromCodePoint(code) : "";
      })
      .replace(/&#(\d+);/g, (_, dec) => {
        const code = parseInt(dec, 10);
        return code > 0 && code <= 1114111 ? String.fromCodePoint(code) : "";
      });
  }

  function cleanTextPreserveLines(text) {
    if (!text) return "";
    return String(text)
      .replace(/\r\n?/g, "\n")
      .replace(/\u0000/g, "")
      .replace(/\t/g, "  ")
      .replace(/[ \u00A0]+\n/g, "\n")
      .replace(/\n{3,}/g, "\n\n")
      .trim();
  }

  function sanitizeUntrustedXml(text) {
    if (!text) return "";
    return String(text).replace(/<\//g, "<\\/");
  }

  function stripXmlTags(str) {
    if (!str) return "";
    return cleanTextPreserveLines(
      decodeHtmlEntities(
        String(str)
          .replace(/<br\s*\/?>/gi, "\n")
          .replace(/<\/(p|paragraph|item|row|tr|li|div|title)>/gi, "\n")
          .replace(/<(td|th)\b[^>]*>/gi, " | ")
          .replace(/<[^>]+>/g, " ")
      ).replace(/[ \t]{2,}/g, " ")
    );
  }

  function normalizeIsoDate(rawDate) {
    if (!rawDate) return null;
    const s = String(rawDate).trim();
    if (/^\d{8}$/.test(s)) {
      return `${s.slice(0, 4)}-${s.slice(4, 6)}-${s.slice(6, 8)}`;
    }
    const isoMatch = s.match(/\b(19\d{2}|20\d{2})-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])\b/);
    if (isoMatch) return `${isoMatch[1]}-${isoMatch[2]}-${isoMatch[3]}`;
    const ymMatch = s.match(/\b(19\d{2}|20\d{2})[\s/-](Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec|\d{2})\b/i);
    if (ymMatch) {
      const p = Date.parse(`${ymMatch[1]} ${ymMatch[2]} 01 UTC`);
      if (!Number.isNaN(p)) return new Date(p).toISOString().split("T")[0];
    }
    const parsed = Date.parse(s);
    if (!Number.isNaN(parsed)) {
      const d = new Date(parsed);
      const yr = d.getUTCFullYear();
      if (yr >= 1970 && yr <= Number(currentYear) + 1) {
        return d.toISOString().split("T")[0];
      }
    }
    if (/^(19\d{2}|20\d{2})$/.test(s)) return `${s}-01-01`;
    return null;
  }

  function safeDomain(url) {
    try {
      return new URL(url).hostname.toLowerCase().replace(/^www\./, "");
    } catch (e) {
      return "unknown";
    }
  }

  function extractPublishedDateFromHtml(htmlString) {
    if (!htmlString) return null;
    const headSlice = String(htmlString).slice(0, 45000);
    const metaPatterns = [
      /<meta[^>]+(?:property|name|itemprop)\s*=\s*["'](?:article:published_time|article:modified_time|og:published_time|publication_date|publish_date|pubdate|datePublished|dc\.date|dcterms\.created|dcterms\.modified)["'][^>]+content\s*=\s*["']([^"']+)["']/i,
      /<meta[^>]+content\s*=\s*["']([^"']+)["'][^>]+(?:property|name|itemprop)\s*=\s*["'](?:article:published_time|article:modified_time|og:published_time|publication_date|publish_date|pubdate|datePublished|dc\.date|dcterms\.created)["']/i,
      /"datePublished"\s*:\s*"([^"]{8,40})"/i,
      /<time[^>]+datetime\s*=\s*["']([^"']{8,40})["']/i
    ];
    for (const pat of metaPatterns) {
      const m = headSlice.match(pat);
      if (m && m[1]) {
        const norm = normalizeIsoDate(m[1]);
        if (norm) return norm;
      }
    }
    return null;
  }

  function extractTitleFromHtml(htmlString) {
    if (!htmlString) return null;
    const m = String(htmlString).slice(0, 25000).match(/<title[^>]*>([\s\S]*?)<\/title>/i);
    if (!m || !m[1]) return null;
    return cleanTextPreserveLines(decodeHtmlEntities(m[1].replace(/\s+/g, " "))).slice(0, 240);
  }

  function extractStructuredHtml(htmlString, maxChars = 60000) {
    if (!htmlString) return { text: "", publishedDate: null, extractedTitle: null };
    const publishedDate = extractPublishedDateFromHtml(htmlString);
    const extractedTitle = extractTitleFromHtml(htmlString);
    let working = String(htmlString)
      .replace(/<!--[\s\S]*?-->/g, " ")
      .replace(/<(script|style|noscript|svg|canvas|iframe|template|form)\b[\s\S]*?<\/\1>/gi, " ");
    const mainMatch = working.match(/<(main|article)\b[^>]*>([\s\S]*?)<\/\1>/i);
    if (mainMatch && mainMatch[2] && mainMatch[2].replace(/<[^>]+>/g, "").trim().length > 400) {
      working = mainMatch[2];
    } else {
      working = working.replace(/<(nav|footer|header|aside)\b[\s\S]*?<\/\1>/gi, " ");
    }
    working = working
      .replace(/<h([1-6])\b[^>]*>([\s\S]*?)<\/h\1>/gi, (_, lvl, inner) => {
        const hTxt = decodeHtmlEntities(inner.replace(/<[^>]+>/g, " ")).replace(/\s+/g, " ").trim();
        return hTxt ? `\n\n${"#".repeat(Number(lvl))} ${hTxt}\n` : "\n";
      })
      .replace(/<li\b[^>]*>/gi, "\n- ")
      .replace(/<\/tr>/gi, "\n")
      .replace(/<(td|th)\b[^>]*>/gi, " | ")
      .replace(/<br\s*\/?>/gi, "\n")
      .replace(/<\/(p|div|section|article|blockquote|ul|ol|table|dl|dt|dd)>/gi, "\n\n")
      .replace(/<[^>]+>/g, " ");
    const decoded = decodeHtmlEntities(working)
      .replace(/[ \t]+\|/g, " |")
      .replace(/\|[ \t]+/g, "| ")
      .replace(/[ \t]{2,}/g, " ");
    return {
      text: cleanTextPreserveLines(decoded).slice(0, maxChars),
      publishedDate,
      extractedTitle
    };
  }

  function repairTruncatedJson(rawText) {
    if (!rawText) return null;
    let s = String(rawText).trim();
    if (s.startsWith("```")) {
      s = s.replace(/^```(?:json)?\s*\n?/i, "").replace(/\n?```\s*$/i, "").trim();
    }
    const firstStart = s.search(/[\[{]/);
    if (firstStart > 0) s = s.slice(firstStart);
    let out = "";
    const stack = [];
    let inString = false;
    let escaped = false;
    for (let i = 0; i < s.length; i++) {
      const ch = s[i];
      if (inString) {
        out += ch;
        if (escaped) escaped = false;
        else if (ch === "\\") escaped = true;
        else if (ch === '"') inString = false;
        continue;
      }
      if (ch === '"') {
        inString = true;
        out += ch;
      } else if (ch === "{") {
        stack.push("}");
        out += ch;
      } else if (ch === "[") {
        stack.push("]");
        out += ch;
      } else if (ch === "}" || ch === "]") {
        out = out.replace(/,\s*$/, "");
        if (stack.length > 0 && stack[stack.length - 1] === ch) {
          stack.pop();
          out += ch;
        }
      } else {
        out += ch;
      }
    }
    if (inString) {
      if (escaped) out += "\\";
      out += '"';
    }
    out = out.replace(/,\s*$/, "");
    if (/:\s*$/.test(out)) out += "null";
    while (stack.length > 0) out += stack.pop();
    return out;
  }

  function parseStructuredJson(rawText) {
    if (!rawText || typeof rawText !== "string") return { parsed: null, repaired: false, error: "empty_response" };
    const trimmed = rawText.trim();
    try {
      return { parsed: JSON.parse(trimmed), repaired: false, error: null };
    } catch (directErr) {
      try {
        const candidate = repairTruncatedJson(trimmed);
        const parsed = JSON.parse(candidate);
        return { parsed, repaired: true, error: null };
      } catch (repairErr) {
        return { parsed: null, repaired: false, error: directErr.message };
      }
    }
  }

  async function fetchAndHydrateDocument(url, options = {}) {
    const { allowPdfMultimodal = true, maxBytes = 24 * 1024 * 1024 } = options;
    const directFirst = buildEndpointList(url, proxyBase ? `${proxyBase}/proxy/${url}` : null);
    for (const target of directFirst) {
      try {
        const res = await fetchWithTimeout(target, {
          headers: {
            "User-Agent": "Mozilla/5.0 (compatible; GeminiMedicalSearch/1.0; +https://ai.google.dev)",
            "Accept": "application/pdf,text/csv,text/html,application/xhtml+xml,text/plain,*/*"
          }
        }, 15000);
        if (!res.ok) continue;
        const contentLength = Number(res.headers.get("content-length") || 0);
        if (contentLength > maxBytes) continue;
        const contentType = (res.headers.get("content-type") || "").toLowerCase();
        const lastModifiedHeader = res.headers.get("last-modified");
        const urlLower = String(url || "").toLowerCase();
        const isPdf = contentType.includes("application/pdf") || /\.pdf(\?|$)/i.test(urlLower);
        if (isPdf && allowPdfMultimodal) {
          const arrayBuffer = await res.arrayBuffer();
          if (arrayBuffer.byteLength > maxBytes || arrayBuffer.byteLength < 64) continue;
          const headerBytes = new Uint8Array(arrayBuffer.slice(0, 5));
          const magic = String.fromCharCode(...headerBytes);
          if (magic.startsWith("%PDF")) {
            return {
              success: true,
              type: "pdf",
              is_native_pdf: true,
              pdf_base64: arrayBufferToBase64(arrayBuffer),
              pdf_byte_length: arrayBuffer.byteLength,
              mime_type: "application/pdf",
              text: `[NATIVE MULTIMODAL PDF DOCUMENT (${Math.round(arrayBuffer.byteLength / 1024)} KB) — Evaluated directly via Gemini native vision/document understanding. URL: ${url}]`,
              publishedDate: null,
              lastModified: normalizeIsoDate(lastModifiedHeader)
            };
          }
        }
        if (contentType.includes("text/plain") || contentType.includes("text/markdown") || contentType.includes("text/csv") || contentType.includes("application/json")) {
          const rawTxt = await res.text();
          const cleaned = cleanTextPreserveLines(rawTxt).slice(0, 48000);
          return {
            success: cleaned.length > 30,
            type: "text",
            is_native_pdf: false,
            text: cleaned,
            publishedDate: null,
            lastModified: normalizeIsoDate(lastModifiedHeader)
          };
        }
        const rawHtml = await res.text();
        const parsedHtml = extractStructuredHtml(rawHtml, 48000);
        if (parsedHtml.text.length > 80) {
          return {
            success: true,
            type: "html",
            is_native_pdf: false,
            text: parsedHtml.text,
            extractedTitle: parsedHtml.extractedTitle,
            publishedDate: parsedHtml.publishedDate,
            lastModified: normalizeIsoDate(lastModifiedHeader)
          };
        }
      } catch (e) {}
    }
    return { success: false, type: "unknown", is_native_pdf: false, text: "", publishedDate: null };
  }

  function resolveThinkingLevel(modelId, stageDesiredLevel) {
    const m = String(modelId || "").toLowerCase();
    if (/omni|image|banana/.test(m) && stageDesiredLevel === "medium") return "high";
    if (stageDesiredLevel === "xhigh") return /hydrogen|flash-latest/.test(m) ? "xhigh" : "high";
    if (["low", "medium", "high"].includes(stageDesiredLevel)) return stageDesiredLevel;
    return "medium";
  }

  function extractTextFromInteraction(data) {
    if (!data) return "";
    if (typeof data.output_text === "string" && data.output_text.length > 0) return data.output_text;
    const parts = [];
    if (Array.isArray(data.steps)) {
      for (const step of data.steps) {
        if ((step.type === "model_output" || !step.type) && Array.isArray(step.content)) {
          for (const block of step.content) {
            if (block && block.type === "text" && typeof block.text === "string") parts.push(block.text);
          }
        }
      }
    }
    if (parts.length > 0) return parts.join("");
    if (Array.isArray(data.outputs)) {
      for (const block of data.outputs) {
        if (block && block.type === "text" && typeof block.text === "string") parts.push(block.text);
      }
    }
    return parts.join("");
  }

  async function callGemini({
    systemInstruction,
    inputBlocks,
    responseSchema,
    thinkingLevel = "medium",
    maxOutputTokens = 65536,
    timeoutMs = 38000
  }) {
    if (!geminiApiKey) {
      return { ok: false, text: "", status: "missing_api_key", error: "Missing Google Gemini API key" };
    }
    diagnostics.generative_calls += 1;
    const resolvedThinking = resolveThinkingLevel(generativeModel, thinkingLevel);
    const safeMaxTokens = clamp(maxOutputTokens || 65536, 8192, 65536);
    const buildPayload = (includeThinking = true, continuationToken = null) => {
      const p = {
        model: generativeModel,
        input: inputBlocks
      };
      if (systemInstruction) p.system_instruction = systemInstruction;
      p.generation_config = { max_output_tokens: safeMaxTokens };
      if (includeThinking && resolvedThinking) p.generation_config.thinking_level = resolvedThinking;
      if (responseSchema) {
        p.response_format = {
          type: "text",
          mime_type: "application/json",
          schema: responseSchema
        };
      }
      if (continuationToken) p.continuation_token = continuationToken;
      return p;
    };
    const headers = {
      "Content-Type": "application/json",
      "x-goog-api-key": geminiApiKey,
      "Api-Revision": "2026-05-20"
    };
    const endpoints = buildEndpointList(geminiDirectUrl, geminiProxyUrl);
    let lastError = "unknown_gemini_error";
    for (const endpoint of endpoints) {
      for (const includeThinking of [true, false]) {
        try {
          const res = await fetchWithTimeout(endpoint, {
            method: "POST",
            headers,
            body: JSON.stringify(buildPayload(includeThinking, null))
          }, timeoutMs);
          const rawBody = await res.text();
          let data = null;
          try { data = JSON.parse(rawBody); } catch (e) {}
          if (!res.ok) {
            const errMsg = data?.error?.message || rawBody.slice(0, 300) || `HTTP ${res.status}`;
            lastError = `HTTP ${res.status}: ${errMsg}`;
            if (res.status === 400 && includeThinking && /thinking/i.test(errMsg)) continue;
            break;
          }
          let combinedText = extractTextFromInteraction(data);
          let status = data?.status || "completed";
          if ((status === "requires_continuation" || status === "REQUIRES_CONTINUATION") && data?.continuation_token && remainingBudgetMs() > 12000) {
            const contRes = await fetchWithTimeout(endpoint, {
              method: "POST",
              headers,
              body: JSON.stringify(buildPayload(includeThinking, data.continuation_token))
            }, 18000);
            if (contRes.ok) {
              const contData = await contRes.json();
              combinedText += extractTextFromInteraction(contData);
              status = contData?.status || "completed";
            }
          }
          if (status === "incomplete") diagnostics.incomplete_generations += 1;
          return {
            ok: combinedText.length > 0 && status !== "failed",
            text: combinedText,
            status,
            usage: data?.usage || null,
            error: status === "failed" ? data?.error?.message || "interaction_failed" : null
          };
        } catch (err) {
          lastError = err.message || "fetch_exception";
          break;
        }
      }
    }
    return { ok: false, text: "", status: "failed", usage: null, error: lastError };
  }

  async function callDecisions(inputBlocks, questionsMap, timeoutMs = 18000) {
    if (!geminiApiKey || verificationEngine === "off" || verificationEngine === "generative_fallback") {
      return { ok: false, answers: null, error: "decisions_disabled_or_missing_key" };
    }
    const qKeys = Object.keys(questionsMap || {});
    if (qKeys.length === 0 || qKeys.length > 1000) {
      return { ok: false, answers: null, error: "invalid_question_count" };
    }
    diagnostics.decisions_api_calls += 1;
    const headers = {
      "Content-Type": "application/json",
      "x-goog-api-key": geminiApiKey
    };
    const payload = {
      model: "gemini-decision-1",
      input: inputBlocks,
      questions: questionsMap
    };
    const endpoints = buildEndpointList(decisionsDirectUrl, decisionsProxyUrl);
    let lastErr = "decisions_unreachable";
    for (const endpoint of endpoints) {
      try {
        const res = await fetchWithTimeout(endpoint, {
          method: "POST",
          headers,
          body: JSON.stringify(payload)
        }, timeoutMs);
        const raw = await res.text();
        let data = null;
        try { data = JSON.parse(raw); } catch (e) {}
        if (res.ok && data && data.answers) {
          diagnostics.decisions_api_status = "healthy";
          return { ok: true, answers: data.answers, usage: data.usage || null, error: null };
        }
        const errCode = data?.error?.code || `HTTP_${res.status}`;
        const errMsg = data?.error?.message || raw.slice(0, 220);
        lastErr = `${errCode}: ${errMsg}`;
        if (res.status === 400) break;
      } catch (e) {
        lastErr = e.message || "decisions_network_error";
      }
    }
    if (diagnostics.decisions_api_status === "not_invoked") {
      diagnostics.decisions_api_status = `fallback (${lastErr.slice(0, 100)})`;
    }
    return { ok: false, answers: null, error: lastErr };
  }

