        hop2Telemetry.added_sources_count = hop2Sources.length;
        sourceObjects = [...sourceObjects, ...hop2Sources];
        evidenceLattice = await buildMedicalEvidenceLattice(sourceObjects, effectiveObjective, detailMode);
        if (remainingBudgetMs() > 14000) {
