  async function getMedlinePlusHerbIndex() {
    const cached = await storageCacheGet("mplus_nccih_herb_index_v2", 7 * 24 * 60 * 60 * 1000);
    if (cached && Array.isArray(cached) && cached.length > 0) return cached;

    const [mpRes, nccihRes] = await Promise.all([
      fetchPublicText("https://medlineplus.gov/druginfo/herb_All.html", "medlineplus_herb_index", 9000),
      fetchPublicText("https://www.nccih.nih.gov/health/herbsataglance", "nccih_herb_index", 9000)
    ]);

    const links = [...CURATED_NCCIH_SUPPLEMENTS];
    const seenUrl = new Set(links.map((x) => x.url));

    if (mpRes.ok) {
      const body = mpRes.text.split(/id="mplus-content"/)[1] || mpRes.text;
      const re = /<a[^>]+href="(https?:\/\/[^"]+)"[^>]*>([\s\S]*?)<\/a>/gi;
      let m;
      while ((m = re.exec(body)) !== null) {
        const url = m[1].trim();
        const name = cleanTextPreserveLines(decodeHtmlEntities(m[2].replace(/<[^>]+>/g, ""))).trim();
        if (!name || seenUrl.has(url)) continue;
        // Exclude ods.od.nih.gov because WAF blocks automated server fetch with HTTP 403
        if (/^(https:\/\/www\.nccih\.nih\.gov\/health\/|https:\/\/medlineplus\.gov\/)/i.test(url) && !/herb_All|druginformation|about|spanish/i.test(url)) {
          seenUrl.add(url);
          links.push({ name, nameLower: name.toLowerCase(), url });
        }
      }
    }

    if (nccihRes.ok) {
      const re2 = /<a[^>]+href="(\/health\/[^"]+)"[^>]*>([\s\S]*?)<\/a>/gi;
      let m2;
      while ((m2 = re2.exec(nccihRes.text)) !== null) {
        const url = `https://www.nccih.nih.gov${m2[1].trim()}`;
        const name = cleanTextPreserveLines(decodeHtmlEntities(m2[2].replace(/<[^>]+>/g, ""))).trim();
        if (!name || name.length < 3 || seenUrl.has(url) || /herbsataglance|providers|safety|know-science/i.test(url)) continue;
        seenUrl.add(url);
        links.push({ name, nameLower: name.toLowerCase(), url });
      }
    }

    if (links.length > 15) await storageCacheSet("mplus_nccih_herb_index_v2", links);
    return links;
  }

  function normHerbStr(s) {
    return String(s || "")
      .toLowerCase()
      .replace(/['\u2018\u2019`]/g, "")
      .replace(/[^a-z0-9\s]/g, " ")
      .replace(/\s+/g, " ")
      .trim();
  }

  function matchHerbIndexEntry(indexList, term) {
    const q = normHerbStr(term);
    if (!q || !Array.isArray(indexList) || indexList.length === 0) return null;
    const exact = indexList.find((x) => normHerbStr(x.nameLower) === q);
    if (exact) return exact;
    return indexList.find((x) => {
      const clean = normHerbStr(x.nameLower);
      return (clean.includes(q) && q.length >= 4) || (clean.length >= 4 && q.includes(clean));
    }) || null;
  }

