  function detectSupplementsInQuery(text, herbIndex) {
    const normText = ` ${normHerbStr(text)} `;
    const found = [];
    for (const key of Object.keys(PUBCHEM_SUPPLEMENT_ALIASES)) {
      const cleanK = normHerbStr(key);
      if (cleanK.length >= 4 && normText.includes(` ${cleanK} `)) found.push(key);
    }
    for (const key of KNOWN_PURE_SUPPLEMENTS) {
      const cleanK = normHerbStr(key);
      if (cleanK.length >= 4 && normText.includes(` ${cleanK} `)) found.push(key);
    }
    for (const h of herbIndex || []) {
      const cleanH = normHerbStr(h.nameLower);
      if (cleanH.length >= 5 && normText.includes(` ${cleanH} `)) found.push(h.name);
    }
    return unique(found).slice(0, 4);
  }

  async function fetchPubChemSupplementProfile(term) {
    const rawLower = String(term || "").trim().toLowerCase();
    const cleanTerm = PUBCHEM_SUPPLEMENT_ALIASES[rawLower] || PUBCHEM_SUPPLEMENT_ALIASES[normHerbStr(rawLower)] || String(term || "").trim();
    if (!cleanTerm) return null;
    const cidRes = await fetchPublicJson(`https://pubchem.ncbi.nlm.nih.gov/rest/pug/compound/name/${encodeURIComponent(cleanTerm)}/cids/JSON`, "pubchem_cid", 7000, { allowNotFound: true });
    const cid = cidRes.data?.IdentifierList?.CID?.[0];
    if (!cid) return null;

    const [dmRes, phRes] = await Promise.all([
      fetchPublicJson(`https://pubchem.ncbi.nlm.nih.gov/rest/pug_view/data/compound/${cid}/JSON?heading=Drug+and+Medication+Information`, "pubchem_pugview", 9000, { allowNotFound: true }),
      fetchPublicJson(`https://pubchem.ncbi.nlm.nih.gov/rest/pug_view/data/compound/${cid}/JSON?heading=Pharmacology+and+Biochemistry`, "pubchem_pugview", 9000, { allowNotFound: true })
    ]);

    const wantedHeadings = new Set([
      "Drug Indication",
      "LiverTox Summary",
      "Drug Classes",
      "EMA Drug Information",
      "Therapeutic Uses",
      "Drug Warnings",
      "Drug-Drug Interactions",
      "Drug-Food Interactions",
      "Pharmacodynamics",
      "Bionecessity",
      "Mechanism of Action",
      "Biological Half-Life",
      "Absorption, Distribution and Excretion"
    ]);
    const extracted = [];
    function walkSection(sec, depth = 0) {
      if (!sec || depth > 5) return;
      const h = sec.TOCHeading || "";
      const keepHere = wantedHeadings.has(h);
      if (keepHere && Array.isArray(sec.Information)) {
        const lines = [];
        for (const info of sec.Information) {
          const swm = info?.Value?.StringWithMarkup;
          if (Array.isArray(swm)) {
            for (const item of swm) {
              if (item?.String && item.String.length > 10) lines.push(item.String);
            }
          }
        }
        if (lines.length > 0) {
          extracted.push(`## ${h}\n${unique(lines).slice(0, 6).join("\n")}`);
        }
      }
      for (const sub of sec.Section || []) walkSection(sub, depth + 1);
    }
    if (dmRes.ok && dmRes.data?.Record?.Section) dmRes.data.Record.Section.forEach((s) => walkSection(s));
    if (phRes.ok && phRes.data?.Record?.Section) phRes.data.Record.Section.forEach((s) => walkSection(s));
    const combinedText = cleanTextPreserveLines(extracted.join("\n\n")).slice(0, 10000);
    if (combinedText.length < 40) return null;
    return {
      cid,
      url: `https://pubchem.ncbi.nlm.nih.gov/compound/${cid}`,
      title: `PubChem Clinical & Pharmacology Profile: ${cleanTerm} (CID ${cid})`,
      text: combinedText,
      source_api: "pubchem_pug_view",
      study_type: "nih_pubchem_profile",
      publishedDate: null
    };
  }

